import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

const api = axios.create({
  baseURL: API_URL,
  headers: { 'Content-Type': 'application/json' }
});

// Helper that unwraps axios errors into a plain, user-friendly message
function getErrorMessage(err) {
  if (err.response && err.response.data) {
    if (err.response.data.errors && err.response.data.errors.length > 0) {
      return err.response.data.errors.map(e => e.message).join(', ');
    }
    return err.response.data.message || 'Something went wrong';
  }
  if (err.request) {
    return 'Could not reach the server. Please check your connection or try again later.';
  }
  return err.message || 'An unexpected error occurred';
}

export const getSubjects = () => api.get('/subjects').then(r => r.data.data).catch(e => { throw new Error(getErrorMessage(e)); });

export const getStudents = () => api.get('/students').then(r => r.data.data).catch(e => { throw new Error(getErrorMessage(e)); });

export const addStudent = (student) => api.post('/students', student).then(r => r.data.data).catch(e => { throw new Error(getErrorMessage(e)); });

export const submitMarks = (payload) => api.post('/marks', payload).then(r => r.data).catch(e => { throw new Error(getErrorMessage(e)); });

export const getStudentResult = (id) => api.get(`/students/${id}/result`).then(r => r.data.data).catch(e => { throw new Error(getErrorMessage(e)); });

export default api;
